import React, { useState } from 'react';
import Navbar from '../components/Navbar';
import { FaPaperPlane, FaRobot, FaUser, FaBrain } from 'react-icons/fa';

function Chat() {
  const [messages, setMessages] = useState([
    { 
      id: 1, 
      text: "Hi there 💙 I'm your AI companion. What's on your mind today?", 
      isUser: false, 
      time: new Date().toLocaleTimeString() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  const generateResponse = (userInput) => {
    const msg = userInput.toLowerCase().trim();
    
    // ============ SPECIFIC WORD DETECTION ============
    
    // MATHS / MATH
    if (msg.includes('math') || msg.includes('maths') || msg.includes('mathematics')) {
      return "Ah, maths! 📐 What's going on with your math studies? Are you preparing for an exam, stuck on a specific topic, or just feeling overwhelmed? I can help you break it down - tell me more about what you're struggling with!";
    }
    
    // PHYSICS
    if (msg.includes('physics')) {
      return "Physics can be tough! ⚡ The concepts can feel abstract. Is there a specific chapter or problem you're finding difficult? Sometimes drawing diagrams or watching visual explanations helps. Want to tell me what's confusing you?";
    }
    
    // CHEMISTRY
    if (msg.includes('chemistry')) {
      return "Chemistry! 🧪 Balancing equations, periodic table, or organic chemistry? Let me know what's challenging you - I can suggest some study techniques or help you break down the concepts.";
    }
    
    // BIOLOGY
    if (msg.includes('biology')) {
      return "Biology 🧬 - so much to memorize! Is it the terminology, processes, or diagrams that are difficult? I can help you create mnemonics or simplify complex topics. What unit are you working on?";
    }
    
    // EXAM
    if (msg.includes('exam') || msg.includes('test') || msg.includes('paper')) {
      return "Exams can be really stressful. 📝 When is your exam? How prepared do you feel? Maybe we can make a small study plan together - just 25 minutes at a time. What subject is worrying you most?";
    }
    
    // STUDY
    if (msg.includes('study') || msg.includes('studying')) {
      return "Studying can be draining! 📚 Have you tried the Pomodoro technique - 25 minutes of study, 5 minute break? What subject are you working on? I can help you stay motivated!";
    }
    
    // HOMEWORK / ASSIGNMENT
    if (msg.includes('homework') || msg.includes('assignment')) {
      return "Homework piling up? 📄 When is it due? Sometimes breaking it into smaller tasks makes it feel less overwhelming. Want to tell me what you need to get done?";
    }
    
    // TEACHER / PROFESSOR
    if (msg.includes('teacher') || msg.includes('professor')) {
      return "Teachers can be hit or miss. 👩‍🏫 Is there something specific about your teacher that's bothering you? Or is it about their teaching style? I'm here to listen.";
    }
    
    // CLASS / LECTURE
    if (msg.includes('class') || msg.includes('lecture')) {
      return "Sitting through long lectures is tough! 💺 Is the class too fast, too slow, or just boring? Maybe I can suggest some active listening techniques that might help.";
    }
    
    // SLEEP
    if (msg.includes('sleep') || msg.includes('tired')) {
      return "Not getting enough sleep affects everything - focus, mood, memory. 😴 How many hours are you sleeping? Maybe we can figure out a better bedtime routine together.";
    }
    
    // STRESS
    if (msg.includes('stress') || msg.includes('stressed') || msg.includes('overwhelm')) {
      return "I hear you. 🧠 Stress can feel like everything is piling up at once. Can we take a moment? Take a deep breath with me. Now, what's ONE thing on your mind right now that feels most urgent? Let's tackle that first.";
    }
    
    // ANXIETY
    if (msg.includes('anxious') || msg.includes('anxiety') || msg.includes('worry')) {
      return "Anxiety is really tough. 🌬️ Let's try grounding - can you tell me 3 things you can see right now? Sometimes bringing ourselves to the present moment helps. What thoughts are running through your head?";
    }
    
    // SAD
    if (msg.includes('sad') || msg.includes('depressed') || msg.includes('unhappy')) {
      return "I'm sorry you're feeling this way. 💙 Do you want to talk about what's making you sad? Sometimes sharing lightens the load. I'm here to listen, no judgment.";
    }
    
    // LONELY
    if (msg.includes('lonely') || msg.includes('alone')) {
      return "Feeling lonely is so hard. 💕 You're not alone right now - I'm here with you. Is there someone you could reach out to, even with a small text? Sometimes a tiny connection helps.";
    }
    
    // ANGRY
    if (msg.includes('angry') || msg.includes('frustrated') || msg.includes('mad')) {
      return "It's okay to feel angry. 🔥 What happened? Sometimes anger tells us something important. Want to talk about what's frustrating you?";
    }
    
    // FRIEND
    if (msg.includes('friend')) {
      return "Friendships can be complicated. 👥 Want to tell me what's going on with your friend? I'm here to listen and help you think it through.";
    }
    
    // FAMILY
    if (msg.includes('mom') || msg.includes('dad') || msg.includes('parent') || msg.includes('family')) {
      return "Family stuff can be really tough. 🏠 Do you want to share what's happening? Remember - it's okay to have boundaries, even with family.";
    }
    
    // CRUSH / RELATIONSHIP
    if (msg.includes('crush') || msg.includes('like') && msg.includes('someone') || msg.includes('relationship')) {
      return "Ah, matters of the heart! 💕 Want to tell me what's going on? I'm a good listener.";
    }
    
    // BORED
    if (msg.includes('bored')) {
      return "Boredom can be so frustrating! 🎮 Want some suggestions? You could try a quick meditation, listen to music, watch something funny, or take a short walk. What sounds good to you?";
    }
    
    // PROCRASTINATION
    if (msg.includes('procrastinate') || msg.includes('procrastinating')) {
      return "Procrastination happens to everyone! ⏰ What are you putting off? Sometimes just doing 2 minutes of the task helps break the resistance. Want to try that together?";
    }
    
    // MOTIVATION
    if (msg.includes('motivation') || msg.includes('no motivation')) {
      return "Losing motivation is totally normal. 🌱 Can we find one tiny win today? Something small you can accomplish? Even making your bed or drinking water counts!";
    }
    
    // GREETINGS
    if (msg.match(/^(hi|hello|hey|heyy|sup|yo)/)) {
      return "Hey there! 👋 What's on your mind today? I'm here to listen.";
    }
    
    // THANK YOU
    if (msg.includes('thank') || msg.includes('thanks')) {
      return "You're welcome! 💙 I'm really glad you're here. Want to talk about something else? I'm all ears.";
    }
    
    // BYE
    if (msg.includes('bye') || msg.includes('goodbye')) {
      return "Take care of yourself! 💫 Remember, I'm always here when you need to talk. Come back anytime. Sending you good vibes!";
    }
    
    // DEFAULT - Ask for more context
    return "I want to understand what you're going through. 💙 Could you tell me a bit more about that? The more you share, the better I can help. What's been on your mind?";
  };

  const sendMessage = () => {
    if (!input.trim()) return;
    
    const userMessage = { 
      id: Date.now(), 
      text: input, 
      isUser: true, 
      time: new Date().toLocaleTimeString() 
    };
    setMessages(prev => [...prev, userMessage]);
    const userInput = input;
    setInput('');
    setIsTyping(true);
    
    setTimeout(() => {
      const response = generateResponse(userInput);
      const aiMessage = { 
        id: Date.now() + 1, 
        text: response, 
        isUser: false, 
        time: new Date().toLocaleTimeString() 
      };
      setMessages(prev => [...prev, aiMessage]);
      setIsTyping(false);
    }, 1000);
  };

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}><FaBrain size={18} /> MindEase AI</h1>
          <p style={styles.subtitle}>I'm here to listen. Really listen.</p>
        </div>

        <div style={styles.chatContainer}>
          <div style={styles.messagesArea}>
            {messages.map(msg => (
              <div key={msg.id} style={{...styles.message, justifyContent: msg.isUser ? 'flex-end' : 'flex-start'}}>
                <div style={styles.messageWrapper}>
                  {!msg.isUser && <FaRobot size={12} style={styles.avatarIcon} />}
                  <div style={{...styles.messageBubble, background: msg.isUser ? '#667eea' : '#f0f0f0', color: msg.isUser ? 'white' : '#333'}}>
                    <p style={styles.messageText}>{msg.text}</p>
                    <span style={styles.messageTime}>{msg.time}</span>
                  </div>
                  {msg.isUser && <FaUser size={12} style={styles.avatarIcon} />}
                </div>
              </div>
            ))}
            {isTyping && (
              <div style={styles.typingContainer}>
                <FaRobot size={12} color="#667eea" />
                <div style={styles.typingIndicator}>
                  <div style={styles.typingDot}></div>
                  <div style={styles.typingDot}></div>
                  <div style={styles.typingDot}></div>
                </div>
                <span style={styles.typingText}>thinking...</span>
              </div>
            )}
          </div>
          
          <div style={styles.inputArea}>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
              placeholder="Type your message..."
              style={styles.input}
            />
            <button onClick={sendMessage} style={styles.sendBtn}>
              <FaPaperPlane size={12} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: { 
    minHeight: '100vh', 
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' 
  },
  navSpacer: { 
    height: '52px' 
  },
  content: { 
    maxWidth: '650px', 
    margin: '0 auto', 
    padding: '0 16px 20px 16px' 
  },
  header: { 
    textAlign: 'center', 
    marginBottom: '16px', 
    color: 'white' 
  },
  title: { 
    fontSize: '20px', 
    marginBottom: '4px', 
    display: 'flex', 
    alignItems: 'center', 
    justifyContent: 'center', 
    gap: '8px' 
  },
  subtitle: { 
    fontSize: '11px', 
    opacity: 0.8 
  },
  chatContainer: { 
    background: 'white', 
    borderRadius: '20px', 
    height: '500px', 
    display: 'flex', 
    flexDirection: 'column', 
    overflow: 'hidden',
    boxShadow: '0 10px 30px rgba(0,0,0,0.1)'
  },
  messagesArea: { 
    flex: 1, 
    overflowY: 'auto', 
    padding: '16px', 
    display: 'flex', 
    flexDirection: 'column', 
    gap: '12px' 
  },
  message: { 
    display: 'flex' 
  },
  messageWrapper: {
    display: 'flex',
    alignItems: 'flex-end',
    gap: '6px',
    maxWidth: '80%'
  },
  avatarIcon: {
    color: '#667eea',
    marginBottom: '4px'
  },
  messageBubble: { 
    padding: '10px 14px', 
    borderRadius: '18px',
    maxWidth: '100%'
  },
  messageText: { 
    margin: 0, 
    fontSize: '13px', 
    lineHeight: 1.4,
    whiteSpace: 'pre-wrap'
  },
  messageTime: { 
    fontSize: '9px', 
    opacity: 0.4, 
    display: 'block', 
    marginTop: '6px' 
  },
  typingContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
    padding: '8px 12px',
    background: '#f0f0f0',
    borderRadius: '20px',
    width: '75px'
  },
  typingIndicator: { 
    display: 'flex', 
    gap: '3px', 
    alignItems: 'center'
  },
  typingDot: { 
    width: '5px', 
    height: '5px', 
    background: '#999', 
    borderRadius: '50%', 
    animation: 'bounce 1s infinite' 
  },
  typingText: {
    fontSize: '9px',
    color: '#999'
  },
  inputArea: { 
    display: 'flex', 
    padding: '12px', 
    gap: '10px', 
    borderTop: '1px solid #eef2f7',
    background: 'white'
  },
  input: { 
    flex: 1, 
    padding: '10px 14px', 
    border: '1px solid #e0e0e0', 
    borderRadius: '25px', 
    outline: 'none', 
    fontSize: '12px',
    transition: 'border 0.2s'
  },
  sendBtn: { 
    background: '#667eea', 
    color: 'white', 
    border: 'none', 
    width: '36px', 
    height: '36px', 
    borderRadius: '50%', 
    cursor: 'pointer', 
    display: 'flex', 
    alignItems: 'center', 
    justifyContent: 'center',
    transition: 'transform 0.2s'
  },
};

// Add animation
const styleSheet = document.createElement("style");
styleSheet.textContent = `
  @keyframes bounce {
    0%, 60%, 100% { transform: translateY(0); }
    30% { transform: translateY(-3px); }
  }
  
  input:focus {
    border-color: #667eea;
  }
  
  button:hover {
    transform: scale(1.05);
  }
`;
document.head.appendChild(styleSheet);

export default Chat;
